def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if len(numbers) < 2:
        return False
    sorted_nums = sorted(numbers)
    for i in range(len(sorted_nums) - 1):
        if sorted_nums[i + 1] - sorted_nums[i] < threshold:
            return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove all spaces
    s = paren_string.replace(' ', '')
    groups = []
    depth = 0
    start = 0
    for i, ch in enumerate(s):
        if ch == '(':
            if depth == 0:
                start = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                groups.append(s[start:i+1])
    return groups

def truncate_number(number: float) -> float:
    """
    Return the decimal part of a positive floating point number.

    The integer part is defined as the largest integer smaller than the number.
    """
    return number - int(number)

def below_zero(operations: list[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    if not numbers:
        return 0.0
    mean_val = sum(numbers) / len(numbers)
    mad = sum(abs(x - mean_val) for x in numbers) / len(numbers)
    return mad

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost = -1
    for idx, (a, b, g, k) in enumerate(carpets, start=1):
        if a <= x <= a + g and b <= y <= b + k:
            topmost = idx
