def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid
    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x - 1][y - 1] = val

    # Special case when N == 1
    if N == 1:
        return grid[0][0]

    INF_NEG = -10**18
    # dp[i1][i2] for current step t
    dp_curr = [[INF_NEG] * N for _ in range(N)]
    dp_curr[0][0] = grid[0][0]  # step 0 (both at start)

    # Maximum steps (including start step 0)
    total_steps = 2 * (N - 1)
    for t in range(1, total_steps + 1):
        dp_next = [[INF_NEG] * N for _ in range(N)]
        # i1 and i2 must be within [max(0, t-(N-1)), min(N-1, t)]
        low = max(0, t - (N - 1))
        high = min(N - 1, t)
        for i1 in range(low, high + 1):
            j1 = t - i1
            if j1 < 0 or j1 >= N:
                continue
            val1 = grid[i1][j1]
            for i2 in range(low, high + 1):
                j2 = t - i2
                if j2 < 0 or j2 >= N:
                    continue
                best_prev = INF_NEG
                # Possible previous moves for walker1: up or left
                for pi1 in (i1, i1 - 1):
                    if pi1 < 0 or pi1 >= N:
                        continue
                    pj1 = (t - 1) - pi1
                    if pj1 < 0 or pj1 >= N:
                        continue
                    for pi2 in (i2, i2 - 1):
                        if pi2 < 0 or pi2 >= N:
                            continue
                        pj2 = (t - 1) - pi2
                        if pj2 < 0 or pj2 >= N:
                            continue
                        prev = dp_curr[pi1][pi2]
                        if prev > best_prev:
                            best_prev = prev
                if best_prev == INF_NEG:
                    continue
                val2 = grid[i2][j2]
                add = val1 if (i1 == i2 and j1 == j2) else val1 + val2
                dp_next[i1][i2] = max(dp_next[i1][i2], best_prev + add)
        dp_curr = dp_next

    return dp_curr[N - 1][N - 1] if dp_curr[N - 1][N - 1] != INF_NEG else 0

def find_number_combinations():
    digits = '123456789'
    combos = []
    for length in range(1, 10):
        for perm in __import__('itertools').permutations(digits, length):
            a = int(''.join(perm))
            b = a * 2
            c = a * 3
            sb, sc = str(b), str(c)
            if all(d in digits for d in sb) and len(set(sb)) == len(sb):
                if all(d in digits for d in sc) and len(set(sc)) == len(sc):
                    combos.append((a, b, c))
    return sorted(combos)

def sum_of_factorials_optimized(n: int) -> int:
    """Return the sum 1! + 2! + ... + n! using an iterative approach."""
    if n < 1:
        raise ValueError("n must be at least 1")
    total = 0
    fact = 1
    for i in range(1, n + 1):
        fact *= i
        total += fact
    return total

def verify_isbn(isbn: str) -> str:
    # Remove hyphens and parse digits
    groups = isbn.split('-')
    digits = []
    for ch in isbn.replace('-', ''):
        if ch.upper() == 'X':
            digits.append(10)
        else:
            digits.append(int(ch))
    # Compute checksum
    total = sum((i + 1) * digits[i] for i in range(10))
    if total % 11 == 0:
        return "Right"
    # Compute correct checksum digit
    s = sum((i + 1) * digits[i] for i in range(9))  # sum without last digit
    correct_digit = s % 11
    corrected_char = 'X' if correct_digit == 10 else str(correct_digit)
    # Reconstruct ISBN with corrected last digit
    new_groups = groups[:-1] + [corrected_char]
    return '-'.join(new_groups)

