def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        deg = n - i
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        if deg == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)
        if deg == 0:
            var_str = ''
        elif deg == 1:
            var_str = 'x'
        else:
            var_str = f'x^{deg}'
        term = sign + coeff_str + var_str
        terms.append(term)
    if not terms:
        return '0'
    if terms[0][0] == '+':
        terms[0] = terms[0][1:]

def decode(encoded: str, original: str, message: str) -> str:
    # If lengths of encoded and original differ, mapping is impossible
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse = {}

    # Build the mapping from encoded to original, checking for contradictions
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            if o_char in reverse:
                # Ensure one-to-one mapping
                return "Failed"
            mapping[e_char] = o_char
            reverse[o_char] = e_char

    # Ensure all 26 uppercase letters are represented in the mapping
    if len(mapping) < 26:
        return "Failed"

    # Decode the message using the established mapping
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return ''.join(decoded_chars)

def largest_prime_factor(n: int) -> int:
    i = 2
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 1
    return n

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    total = 1  # sequence that ends at 'last' without appending more numbers
    max_next = last // 2
    for k in range(1, max_next + 1):
        total += count_sequences(n, k, memo)
    memo[last] = total
    return total

