def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    GCD(P, Q) == x0 and LCM(P, Q) == y0.
    """
    if y0 % x0 != 0:
        return 0
    k = y0 // x0
    count = 0
    import math
    sqrt_k = math.isqrt(k)
    for a in range(1, sqrt_k + 1):
        if k % a == 0:
            b = k // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ''
    index_map = {c: i for i, c in enumerate(inorder)}
    def recurse(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right:
            return ''
        root = postorder[post_right]
        idx = index_map[root]
        left_count = idx - in_left
        left_pre = recurse(in_left, idx - 1, post_left, post_left + left_count - 1)
        right_pre = recurse(idx + 1, in_right, post_left + left_count, post_right - 1)
        return root + left_pre + right_pre
    return recurse(0, len(inorder) - 1, 0, len(postorder) - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    max_depth = 10
    queue = [(A, 0)]
    visited = {A}
    while queue:
        current, steps = queue.pop(0)
        if current == B:
            return steps
        if steps == max_depth:
            continue
        for src, dst in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + dst + current[idx + len(src):]
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping occurrences
    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    from collections import deque

    start = str(n)
    q = deque([start])
    visited = {int(start)}

    while q:
        cur = q.popleft()
        digits = list(cur)
        for idx, d in enumerate(digits):
            for x, y in rules:
                if d == str(x):
                    new_digits = digits.copy()
                    new_digits[idx] = str(y)
                    new_num_str = "".join(new_digits)
                    new_val = int(new_num_str)
                    if new_val not in visited:
                        visited.add(new_val)
                        q.append(new_num_str)

    return len(visited)

def calculate_score(system: int, points: str) -> list:
    scores = []
    player, opponent = 0, 0
    for ch in points:
        if ch == 'W':
            player += 1
        else:  # assume 'L' for opponent
            opponent += 1
        if (player >= system or opponent >= system) and abs(player - opponent) >= 2:
            scores.append(f"{player}:{opponent}")
            player, opponent = 0, 0
    if player or opponent:
        scores.append(f"{player}:{opponent}")
    return scores

def remaining_trees_after_clearing(l: int, areas: list) -> int:
    if not areas:
        return l
    # Normalize intervals as [start, end) assuming inclusive start, exclusive end
    merged = []
    for start, end in sorted(areas, key=lambda x: x[0]):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    cleared = sum(end - start for start, end in merged)
    remaining = max(l - cleared, 0)
    return remaining

def max_herb_value(T: int, M: int, herbs: list[tuple[int, int]]) -> int:
    dp = [0] * (T + 1)
    for cost, val in herbs:
        if cost > T:
            continue
        for t in range(T, cost - 1, -1):
            nv = dp[t - cost] + val
            if nv > dp[t]:
                dp[t] = nv
    return max(dp)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Use only the first n volumes just in case the list is longer
    volumes = volumes[:n]
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True
    # Find the largest capacity that can be reached
    max_occupied = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied = i
            break
    return V - max_occupied

def mod_inverse(a, b):
    # Extended Euclidean Algorithm to find integers x, y such that a*x + b*y = gcd(a, b)
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        g, x1, y1 = extended_gcd(y, x % y)
        # Update x and y using the results from recursion
        return g, y1, x1 - (x // y) * y1

    g, x, _ = extended_gcd(a, b)
    if g != 1:
        return None  # Inverse does not exist if a and b are not coprime
    return x % b  # Ensure the inverse is positive modulo b

def find_most_unhappy_day(schedule) -> int:
    max_diff = 0
    max_day = 0
    for i, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            diff = total - 8
            if diff > max_diff:
                max_diff = diff
                max_day = i
    return max_day

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    max_len = 0
    for i in range(n):
        cur = lis[i] + lds[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
